const FINDINGS = {
  type: 'object',
  properties: {
    verdict: { type: 'string', description: 'two or three sentences: does this segment look amazing, and why or why not' },
    score: { type: 'number', description: '1-10, 10 = shippable AAA horror look' },
    strengths: { type: 'array', items: { type: 'string' } },
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          image: { type: 'string', description: 'file name the problem is visible in' },
          severity: { type: 'string', enum: ['blocker', 'major', 'minor'] },
          area: { type: 'string', description: 'colour | exposure | lighting | materials | geometry | vegetation | water | weather | creatures | ui | story | performance' },
          issue: { type: 'string', description: 'what is wrong, where in the frame' },
          cause: { type: 'string', description: 'likely cause if you can tell from the code or the frame' },
          fix: { type: 'string', description: 'concrete change to make' },
        },
        required: ['image', 'severity', 'area', 'issue', 'fix'],
      },
    },
  },
  required: ['verdict', 'score', 'findings'],
}

const CHECKED = {
  type: 'object',
  properties: {
    kept: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          image: { type: 'string' },
          severity: { type: 'string', enum: ['blocker', 'major', 'minor'] },
          area: { type: 'string' },
          issue: { type: 'string' },
          fix: { type: 'string' },
          why_real: { type: 'string', description: 'what you saw in the image that confirms it' },
        },
        required: ['image', 'severity', 'area', 'issue', 'fix', 'why_real'],
      },
    },
    dropped: {
      type: 'array',
      items: {
        type: 'object',
        properties: { issue: { type: 'string' }, why_not: { type: 'string' } },
        required: ['issue', 'why_not'],
      },
    },
    missed: {
      type: 'array',
      description: 'problems the first critic did not report',
      items: {
        type: 'object',
        properties: {
          image: { type: 'string' },
          severity: { type: 'string', enum: ['blocker', 'major', 'minor'] },
          area: { type: 'string' },
          issue: { type: 'string' },
          fix: { type: 'string' },
        },
        required: ['image', 'severity', 'area', 'issue', 'fix'],
      },
    },
    score: { type: 'number' },
  },
  required: ['kept', 'dropped', 'missed', 'score'],
}

const imageList = seg => seg.images.map(i => `- ${PROJECT}/${i.file} : ${i.what}`).join('\n')

const COMMON = `You are reviewing the look of "Cretacea: Blackout", a first-person horror game in Unity 6 HDRP (a dinosaur
theme park at night in a storm, a security guard with a flashlight). The owner's verdict on an earlier build was: "the
colors are off, it doesn't look right ... make this game look amazing ... it needs to be perfect". A team has since
rebuilt the look. Your job is to judge the result as a demanding art director who also plays horror games.

Project folder: ${PROJECT}  (review round ${ROUND})
Read first: ${PROJECT}/docs/LOOK_BIBLE.md (sections 2, 3, 4: the acceptance criteria, the palette, exposure).

Context for round 4: this is the fourth review. Review 3 (one build round ago) scored these segments 6 to 8 out of 10,
with no blockers, 23 majors and 61 minors. Its findings are in ${PROJECT}/docs/review3/<segment>.md and
<segment>_check.md (the two night segments are filed as night_a and night_b; read the _check file for your segment to
know what was wrong then; the captures of that round are in ~/CretaceaUnityClones/_refs/review3/ with the
same file names, so you can compare a frame with its older version when it helps). Since then the team changed: the
flashlight (the hot spot follows the albedo of the surface, the bounce no longer lights the ceiling, a small fill on the
arm), the tree impostors, the valley woodland and tall grass, the T. rex reveal and the valley at night (beacons,
reflectors, a wet road), the Visitor Center rooms (dressing, props) and their light (lobby colour, emergency heads,
battery units, loading dock), the service path walls, the E-0 gate, the ending shot, the interface, the opening's
staging, the afternoon sun (lower and warmer), the dawn haze and the storm walls. The free-camera storm frames now carry
their rain with them (review 3's vertical seams were a capture artefact). Judge what you see now with fresh eyes: do not
assume an old problem is fixed, and do not assume it is still there. Say plainly whether each of review 3's majors for
your segment is fixed, partly fixed or still there.

Rules:
- Look at EVERY image listed for your segment with the Read tool (they are 1280x720 PNG; read them one or two at a
  time, never in one big batch). Judge only what you can see. Do not start Unity and do not edit any file.
- A capture with the HUD is a real Play-mode frame. A capture without the HUD comes from a free camera (or a cutscene).
  Free-camera captures have two known capture artefacts that are NOT game bugs and must not be reported: rain, ground
  mist and lightning glow are placed around the player's own camera (a free camera far from the player sees seams, a
  box edge or none), and the indoor look follows the player, not the free camera.
- Compare against a shipped AAA horror game (Alien: Isolation, Resident Evil 7, The Last of Us Part I at night): natural
  colour, a full tonal range, readable silhouettes, believable materials and fixtures, coherent light sources, no
  primitive boxes, nothing floating, nothing blown out, nothing crushed to black, no banding, no flat fill.
- Be specific: name the image, say where in the frame, what is wrong, why, and what to change. If you can find the
  cause in the code (Assets/Editor/LookPass/*.cs, Assets/Editor/WorldBuilder/*.cs, Assets/Scripts/Core/AtmosphereController.cs,
  Assets/Scripts/Player/FlashlightController.cs), name the file and the value. Do not pad: a finding must be something
  a player or the owner would notice.
- Severity: blocker = breaks the look or the game in this frame; major = clearly visible flaw; minor = polish.
- Also list what works (strengths), briefly.`

phase('Critique')
const results = await pipeline(
  SEGMENTS,
  seg => agent(
    `${COMMON}\n\nYour segment: ${seg.title}\nFocus: ${seg.focus}\n\nImages:\n${imageList(seg)}\n\nReturn your verdict, a score, strengths and findings.`,
    { label: `critic:${seg.key}`, phase: 'Critique', schema: FINDINGS, model: 'opus', effort: 'max' }
  ),
  (review, seg) => {
    if (!review) return null
    const list = (review.findings || []).map((f, i) => `${i + 1}. [${f.severity}] ${f.image} (${f.area}): ${f.issue} -> ${f.fix}`).join('\n') || '(none)'
    return agent(
      `${COMMON}\n\nYour segment: ${seg.title}\nFocus: ${seg.focus}\n\nImages:\n${imageList(seg)}\n\n` +
      `A first critic gave this segment ${review.score}/10 and reported:\n${list}\n\n` +
      `You are the second, sceptical reviewer. Look at the images yourself. For each reported finding decide: is it really ` +
      `visible in the named image and would a player notice? Keep it (with what you saw) or drop it (with why). Correct the ` +
      `severity if it is wrong. Then report anything the first critic MISSED. Give your own score.`,
      { label: `check:${seg.key}`, phase: 'Challenge', schema: CHECKED, model: 'opus', effort: 'max' }
    ).then(check => ({ key: seg.key, title: seg.title, first: review, check }))
  }
)

const done = results.filter(Boolean)
log(`${done.length}/${SEGMENTS.length} segments reviewed`)
return done.map(r => ({
  key: r.key,
  title: r.title,
  firstScore: r.first.score,
  secondScore: r.check ? r.check.score : null,
  verdict: r.first.verdict,
  strengths: r.first.strengths || [],
  kept: r.check ? r.check.kept : r.first.findings,
  missed: r.check ? r.check.missed : [],
  dropped: r.check ? r.check.dropped : [],
}))
